from pydantic import BaseModel, Field, ValidationError
from typing import List, Dict, Any

class SensorReading(BaseModel):
    sensor_id: str
    temperature: float = Field(ge=-50.0, le=150.0)
    humidity: float = Field(ge=0.0, le=100.0)

def parse_readings(stream):
    for raw in stream:
        try:
            reading = SensorReading(**raw)
            yield {'status': 'valid', 'data': reading.model_dump()}
        except ValidationError as e:
            yield {'status': 'dlq', 'raw': raw, 'error': str(e)}

raw_stream = [
    {'sensor_id': 'S1', 'temperature': 24.5, 'humidity': 45.0},
    {'sensor_id': 'S2', 'temperature': 'CORRUPT', 'humidity': 50.0},
    {'sensor_id': 'S3', 'temperature': 31.0, 'humidity': 110.0}
]

results = list(parse_readings(raw_stream))
print('Validos:', sum(1 for r in results if r['status'] == 'valid'))
print('DLQ:', sum(1 for r in results if r['status'] == 'dlq'))
